      actions.push({
        file: description,
        what: `description specFolder -> ${pointer}`,
        apply: () => {
          const current = JSON.parse(readForWrite(description));
          current.specFolder = pointer;
          writeAtomic(description, `${JSON.stringify(current, null, 2)}\n`);
